    MA([("kunt u me vertellen …?","pode dizer-me …?"),("plattegrond","mapa"),("geen flauw idee","nem ideia"),("rechtdoor","em frente")], "Orientação.", ["v-kunt-u-me-vertellen","v-plattegrond","v-geen-flauw-idee","v-rechtdoor"]),
    MC("Transforme: «Waar is het station?» → «Weet u ___»", ["*waar het station is?","waar is het station?|Verbo no fim.","of waar het station is?|Sem «of»."], "Palavra interrogativa + verbo no fim.", ["v-kunt-u-me-vertellen"]),
    BS("Sabes a que horas fecha a loja?", ["Weet","jij","hoe","laat","de","winkel","dichtgaat?","gaat","dicht"], ["Weet jij hoe laat de winkel dichtgaat"], "Separável junto no fim.", ["v-kunt-u-me-vertellen"]),
    TR("pt-nl","Pode dizer-me onde é a estação?", ["Kunt u me vertellen waar het station is","Kunt u mij vertellen waar het station is","Weet u waar het station is"], "Verbo no fim.", ["v-kunt-u-me-vertellen"]),
    TR("pt-nl","Não faço a mínima ideia.", ["Ik heb geen flauw idee","Geen flauw idee"], "Expressão.", ["v-geen-flauw-idee"]),
    FE(["Weet","u","waar","de","apotheek","zijn?"], 5, "is", "Sujeito singular: is.", ["v-kunt-u-me-vertellen"]),
    DL([("Toerist","Kunt u me vertellen hoe ik bij het Rijksmuseum kom?","Pode dizer-me como chego ao Rijksmuseum?"),("Voorbijganger","","")], ["*Ja, ga hier rechtdoor tot het kruispunt en dan linksaf. Het is vijf minuten lopen.","Ik weet hoe ik kom.|Não ajuda.","Het museum is waar.|Não faz sentido."], "Indicar o caminho.", ["v-rechtdoor","v-kruispunt"]),
    FB("Op de ___ zie je waar alle winkels zijn.", ["plattegrond"], "Mapa.", ["v-plattegrond"], choices=["plattegrond","kruispunt","idee"], tr="No mapa vês onde estão todas as lojas."),
    LI("Weet je toevallig wie de nieuwe buren zijn?", ["Weet je toevallig wie de nieuwe buren zijn","Weet je toevallig wie de nieuwe buren zijn?"], "Sabes por acaso quem são os novos vizinhos?", "toevallig = por acaso.", ["v-kunt-u-me-vertellen"]),
    WO("Sabe quanto custa?", ["Weet","u","hoeveel","het","kost?"], "Verbo no fim.", ["v-hoeveel-conj"]),
